type GherkinKeywords = { feature: string; background: string; rule: string; scenario: string; scenarioOutline: string; examples: string; given: string; when: string; then: string; and: string; but: string };
const languageKeywords: Record<GherkinLanguage, GherkinKeywords> = { pt: { feature: "Funcionalidade", background: "Contexto", rule: "Regra", scenario: "Cenário", scenarioOutline: "Esquema do Cenário", examples: "Exemplos", given: "Dado", when: "Quando", then: "Então", and: "E", but: "Mas" }, en: { feature: "Feature", background: "Background", rule: "Rule", scenario: "Scenario", scenarioOutline: "Scenario Outline", examples: "Examples", given: "Given", when: "When", then: "Then", and: "And", but: "But" } };
type Module = { id: string; number: string; title: string; level: string; description: string; lessons: string[]; locked?: boolean };
type Question = { moduleId: string; number: string; prompt: string; options: { id: string; label: string; text: string }[]; answer: string; rationale: string; source?: string };

function readStoredJson<T>(key: string, fallback: T): T {
  try {
    const value = localStorage.getItem(key);
    return value ? (JSON.parse(value) as T) : fallback;
  } catch {
    localStorage.removeItem(key);
    return fallback;
  }
}

