const glossaryItems = [{ command: "cy.visit()", meaning: "Abre uma URL no navegador de teste.", when: "Use no início do cenário, quando o fluxo precisa partir de uma página específica.", docs: "https://docs.cypress.io/api/commands/visit" }, { command: "cy.get()", meaning: "Consulta elementos do DOM por seletor.", when: "Use quando o elemento possui um seletor estável, como data-testid.", docs: "https://docs.cypress.io/api/commands/get" }, { command: "cy.contains()", meaning: "Localiza um elemento pelo texto visível.", when: "Use quando a ação é expressa pelo conteúdo que a pessoa vê.", docs: "https://docs.cypress.io/api/commands/contains" }, { command: ".click()", meaning: "Interage com um elemento clicável.", when: "Use para representar ações como clicar em botão, link ou item.", docs: "https://docs.cypress.io/api/commands/click" }, { command: ".should()", meaning: "Cria uma asserção sobre o estado esperado.", when: "Use no Então para verificar o resultado do comportamento.", docs: "https://docs.cypress.io/api/commands/should" }, { command: "cy.intercept()", meaning: "Intercepta e observa ou controla requisições de rede.", when: "Use para isolar respostas, aguardar APIs ou testar estados previsíveis.", docs: "https://docs.cypress.io/api/commands/intercept" }];
const regressionWorkflow = `name: Testes de regressão\n\non:\n  pull_request:\n  schedule:\n    - cron: '0 3 * * 1-5'\n\njobs:\n  cypress:\n    runs-on: ubuntu-24.04\n    steps:\n      - uses: actions/checkout@v4\n      - uses: cypress-io/github-action@v7\n        with:\n          build: npm run build\n          start: npm start\n          browser: chrome`;

function CodeBlock({ label, code }: { label: string; code: string }) {
  const [copied, setCopied] = useState(false);
  const copy = async () => { await navigator.clipboard.writeText(code); setCopied(true); window.setTimeout(() => setCopied(false), 1800); };
  return <div className="overflow-hidden rounded-xl border border-[var(--app-border)] bg-[var(--app-code)]"><div className="flex items-center justify-between border-b border-[var(--app-border)] px-4 py-2"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-[var(--app-dim)]">{label}</span><button onClick={copy} className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[.1em] text-[#18d8e8] hover:text-[var(--app-text)]" aria-label={`Copiar ${label}`}>{copied ? <><CheckCheck className="h-3.5 w-3.5" /> Copiado!</> : <><Copy className="h-3.5 w-3.5" /> Copiar</>}</button></div><pre className="overflow-x-auto p-4 font-mono text-xs leading-6 text-[var(--app-code-text)]"><code>{code}</code></pre></div>;
}
GlobalWorkerOptions.workerSrc = "https://unpkg.com/pdfjs-dist@6.2.108/build/pdf.worker.min.mjs";

export default function Home() {
  const { theme, toggleTheme } = useTheme();
  const [mode, setMode] = useState<Mode>("home");
  const [activeModule, setActiveModule] = useState("fundamentos");
  const [selectedLessonIndex, setSelectedLessonIndex] = useState(0);
  const [lessonDrafts, setLessonDrafts] = useState<Record<string, string>>(() => readStoredJson("gherkin-lesson-drafts", {}));
  const [completedLessons, setCompletedLessons] = useState<string[]>(() => readStoredJson("gherkin-completed-lessons", []));
  const [questionIndex, setQuestionIndex] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const [submitted, setSubmitted] = useState(false);
  const [story, setStory] = useState(() => localStorage.getItem("gherkin-story") ?? "");
  const [pdfName, setPdfName] = useState("");
  const [pdfStatus, setPdfStatus] = useState<string | null>(null);
  const [conversionText, setConversionText] = useState("");
  const [conversionFeedback, setConversionFeedback] = useState<string | null>(null);
  const [conversionChecks, setConversionChecks] = useState<Record<string, boolean>>({});
  const [conversionFinished, setConversionFinished] = useState(false);
  const [terminalAnswers, setTerminalAnswers] = useState<Record<string, string>>({});
  const [terminalFeedback, setTerminalFeedback] = useState<Record<string, string>>({});
  const [gherkinLanguage, setGherkinLanguage] = useState<GherkinLanguage>("pt");
  const exportFeature = () => { const title = featureText.match(/^\\s*(?:Feature|Funcionalidade):\\s*(.+)$/m)?.[1]?.trim() || "minha-feature"; const safeName = title.normalize("NFD").replace(/[\\u0300-\\u036f]/g, "").replace(/[^a-zA-Z0-9]+/g, "-").replace(/^-|-$/g, "").toLowerCase() || "minha-feature"; const blob = new Blob([featureText], { type: "text/plain;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${safeName}.feature`; document.body.appendChild(anchor); anchor.click(); anchor.remove(); URL.revokeObjectURL(url); };
  const validateConversion = () => { const checks = Object.fromEntries(conversionCriteria.map((item) => [item.key, conversionText.includes(item.expected.split("(")[0])])) as Record<string, boolean>; setConversionChecks(checks); const score = Object.values(checks).filter(Boolean).length; setConversionFinished(true); setConversionFeedback(score === conversionCriteria.length ? "Conversão concluída. Todas as etapas foram representadas." : `Você acertou ${score} de ${conversionCriteria.length} etapas. Revise os itens destacados.`); };
  const validateTerminal = (exercise: typeof terminalExercises[number]) => { const answer = terminalAnswers[exercise.id]?.trim().toLowerCase() ?? ""; setTerminalFeedback((items) => ({ ...items, [exercise.id]: answer === exercise.expected ? "Correto. Este é o comando esperado." : `Revise. O comando esperado é: ${exercise.expected}` })); };
  const [featureText, setFeatureText] = useState(() => localStorage.getItem("gherkin-feature") ?? starterFeature);
  const [syntaxResult, setSyntaxResult] = useState<string | null>(null);
  const [completed, setCompleted] = useState<string[]>(() => readStoredJson("gherkin-completed", []));
  const active = modules.find((item) => item.id === activeModule) ?? modules[0];
  const moduleQuestions = questions.filter((item) => item.moduleId === activeModule);
  const question = moduleQuestions[questionIndex] ?? questions[0];
  const progress = Math.round(((completed.length + completedLessons.length) / (questions.length + modules.reduce((sum, item) => sum + item.lessons.length, 0))) * 100);
  const moduleCompletion = (moduleId: string) => { const lessonsTotal = modules.find((item) => item.id === moduleId)?.lessons.length ?? 0; const lessonsDone = completedLessons.filter((item) => item.startsWith(`${moduleId}-`)).length; const questionsTotal = questions.filter((item) => item.moduleId === moduleId).length; const questionsDone = completed.filter((item) => item.startsWith(`${moduleId}-`)).length; const total = lessonsTotal + questionsTotal; return total ? Math.round(((lessonsDone + questionsDone) / total) * 100) : 0; };
  const correct = submitted && selected === question.answer;

  const allLessonsDone = active.lessons.every((_, index) => completedLessons.includes(`${activeModule}-lesson-${index}`));
  const toggleLesson = (index: number) => { const key = `${activeModule}-lesson-${index}`; setCompletedLessons((items) => items.includes(key) ? items.filter((item) => item !== key) : [...items, key]); };

  useEffect(() => localStorage.setItem("gherkin-completed", JSON.stringify(completed)), [completed]);
  useEffect(() => localStorage.setItem("gherkin-completed-lessons", JSON.stringify(completedLessons)), [completedLessons]);
  useEffect(() => localStorage.setItem("gherkin-story", story), [story]);
  useEffect(() => localStorage.setItem("gherkin-feature", featureText), [featureText]);
  useEffect(() => localStorage.setItem("gherkin-lesson-drafts", JSON.stringify(lessonDrafts)), [lessonDrafts]);

  const chooseModule = (id: string) => { setActiveModule(id); setQuestionIndex(0); setSelected(null); setSubmitted(false); setMode("learn"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const submit = () => { if (!selected) return; setSubmitted(true); if (selected === question.answer && !completed.includes(`${question.moduleId}-${question.number}`)) setCompleted((items) => [...items, `${question.moduleId}-${question.number}`]); };
  const nextQuestion = () => { setQuestionIndex((value) => (value + 1) % moduleQuestions.length); setSelected(null); setSubmitted(false); };
  const validateFeature = (value = featureText) => { const keywords = languageKeywords[gherkinLanguage]; const required = [`${keywords.feature}:`, `${keywords.scenario}:`, keywords.given, keywords.when, keywords.then]; const missing = required.filter((token) => !value.includes(token)); setSyntaxResult(missing.length ? `Revise a estrutura em ${gherkinLanguage === "pt" ? "português" : "inglês"}: falta ${missing.join(", ")}.` : `Estrutura mínima em ${gherkinLanguage === "pt" ? "português" : "inglês"} encontrada. Compare os passos com a história e revise a clareza do comportamento.`); };
  const handlePdf = async (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; if (!file) return; if (file.type !== "application/pdf") { setPdfStatus("Selecione um arquivo PDF."); return; } setPdfName(file.name); setPdfStatus("Lendo o arquivo…"); try { const buffer = await file.arrayBuffer(); const pdf = await getDocument({ data: buffer }).promise; let extracted = ""; for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1) { const page = await pdf.getPage(pageNumber); const content = await page.getTextContent(); extracted += `${content.items.map((item) => ("str" in item ? item.str : "")).join(" ")}\n\n`; } setStory(extracted.trim()); setPdfStatus(`${pdf.numPages} página${pdf.numPages === 1 ? "" : "s"} importada${pdf.numPages === 1 ? "" : "s"}. Revise o texto antes de usar.`); } catch { setPdfStatus("Não foi possível ler este PDF. Você pode colar o texto manualmente."); } };

  return <div className="min-h-screen bg-[var(--app-bg)] text-[var(--app-text)]">
    <header className="sticky top-0 z-20 border-b border-[var(--app-border-subtle)] bg-[var(--app-bg)]/90 backdrop-blur-xl"><div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-5 lg:px-10"><button onClick={() => setMode("home")} className="flex items-center gap-3" aria-label="Voltar ao início"><div className="grid h-10 w-10 place-items-center overflow-hidden rounded-xl border border-[#f34ba8]/50 bg-[var(--app-brand)]"><span aria-hidden="true" className="font-mono text-sm font-bold tracking-[-.12em] text-[#18d8e8]">GA</span></div><div className="leading-none"><span className="font-display text-base font-bold">Gherkin</span><span className="ml-1 font-mono text-[10px] uppercase tracking-[.22em] text-[#f34ba8]">Academy</span></div></button><nav className="hidden items-center gap-8 text-sm text-[var(--app-nav)] md:flex"><button onClick={() => setMode("learn")} className="hover:text-[var(--app-text)]">Aprender</button><button onClick={() => setMode("practice")} className="hover:text-[var(--app-text)]">Praticar</button><button onClick={() => setMode("create")} className="hover:text-[var(--app-text)]">Criar testes</button><a className="hover:text-[var(--app-text)]" href="https://cucumber.io/docs/gherkin/reference/" target="_blank" rel="noreferrer">Referência</a></nav><div className="flex items-center gap-3"><span className="hidden font-mono text-[10px] text-[var(--app-dim)] sm:block">{completed.length + completedLessons.length}/{questions.length + modules.reduce((sum, item) => sum + item.lessons.length, 0)} ESTUDOS</span><div className="h-2 w-20 overflow-hidden rounded-full bg-[var(--app-soft)]"><div className="h-full rounded-full bg-[#18d8e8] transition-all duration-500" style={{ width: `${progress}%` }} /></div><button type="button" onClick={() => toggleTheme?.()} aria-pressed={theme === "dark"} aria-label={theme === "dark" ? "Ativar modo claro" : "Ativar modo escuro"} title={theme === "dark" ? "Ativar modo claro" : "Ativar modo escuro"} className="grid h-9 w-9 place-items-center rounded-lg border border-[var(--app-border-strong)] bg-[var(--app-soft)] text-[#18d8e8] hover:border-[#18d8e8]/60 hover:text-[var(--app-text)]">{theme === "dark" ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><Button size="sm" onClick={() => setMode("create")} className="bg-[#f34ba8] text-[var(--app-primary-foreground)] hover:bg-[#ff74bc]">Abrir bancada</Button></div></div></header>

    {mode === "home" && <main><section className="relative overflow-hidden border-b border-[var(--app-border-subtle)]"><div className="absolute inset-0 hero-backdrop" /><div className="pointer-events-none absolute inset-0 opacity-20 [background-image:linear-gradient(rgba(24,216,232,.16)_1px,transparent_1px),linear-gradient(90deg,rgba(243,75,168,.12)_1px,transparent_1px)] [background-size:64px_64px]" /><div className="relative mx-auto max-w-[1440px] px-5 pb-20 pt-24 lg:px-10"><div className="max-w-[780px]"><div className="mb-7 flex items-center gap-3 font-mono text-[11px] uppercase tracking-[.25em] text-[#18d8e8]"><span className="h-px w-10 bg-[#18d8e8]" /> sua bancada de qualidade</div><h1 className="font-display text-5xl font-bold leading-[.98] tracking-[-.06em] sm:text-6xl lg:text-7xl">Aprenda a escrever.<br /><em className="not-italic text-[#f34ba8]">Crie para validar.</em></h1><p className="mt-7 max-w-[640px] text-lg leading-8 text-[var(--app-body-muted)]">Escolha como quer começar. Estude a linguagem passo a passo ou abra uma bancada para transformar sua história de usuário em uma especificação Gherkin.</p><div className="mt-8 flex items-center gap-4"><div aria-label="Erica de Souza" role="img" className="grid h-16 w-16 shrink-0 place-items-center rounded-full border-2 border-[#f34ba8]/70 bg-[var(--app-brand)] font-display text-lg font-bold text-[#ff82c0] shadow-[0_0_28px_rgba(243,75,168,.22)]">ES</div><div><p className="font-display text-base font-semibold">Erica de Souza</p><p className="mt-1 text-xs text-[var(--app-muted)]">QA, Gherkin e automação de testes</p><div className="mt-3 flex flex-wrap gap-3"><a href="https://www.linkedin.com/in/erica-souza/" target="_blank" rel="noreferrer" aria-label="Abrir LinkedIn de Erica de Souza" className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[.1em] text-[#18d8e8] hover:text-[var(--app-text)]"><Linkedin className="h-3.5 w-3.5" /> LinkedIn <ExternalLink className="h-3 w-3" /></a><a href="https://www.youtube.com/@Erica-QA" target="_blank" rel="noreferrer" aria-label="Abrir YouTube Erica QA" className="inline-flex items-center gap-1.5 font-mono text-[10px] uppercase tracking-[.1em] text-[#ff82c0] hover:text-[var(--app-text)]"><Youtube className="h-3.5 w-3.5" /> YouTube <ExternalLink className="h-3 w-3" /></a></div></div></div></div><div className="mt-14 grid max-w-[1040px] gap-4 md:grid-cols-2"><button onClick={() => setMode("learn")} className="group rounded-2xl border border-[#18d8e8]/40 bg-[var(--app-cyan-panel)]/90 p-7 text-left shadow-[0_0_45px_rgba(24,216,232,.08)] transition hover:-translate-y-1 hover:border-[#18d8e8]"><div className="flex items-start justify-between"><div className="grid h-12 w-12 place-items-center rounded-xl border border-[#18d8e8]/30 bg-[#18d8e8]/10"><BookOpen className="h-5 w-5 text-[#18d8e8]" /></div><span className="font-mono text-[10px] uppercase tracking-[.16em] text-[#18d8e8]">trilha guiada</span></div><h2 className="mt-10 font-display text-2xl font-semibold">Aprender Gherkin</h2><p className="mt-3 max-w-md text-sm leading-6 text-[var(--app-cyan-soft)]">Leia o conteúdo, veja exemplos e depois pratique com uma atividade de verificação.</p><span className="mt-7 inline-flex items-center gap-2 font-mono text-xs text-[#18d8e8]">Começar pelo conteúdo <ChevronRight className="h-4 w-4 transition group-hover:translate-x-1" /></span></button><button onClick={() => setMode("create")} className="group rounded-2xl border border-[#f34ba8]/40 bg-[var(--app-pink-panel)]/90 p-7 text-left shadow-[0_0_45px_rgba(243,75,168,.08)] transition hover:-translate-y-1 hover:border-[#f34ba8]"><div className="flex items-start justify-between"><div className="grid h-12 w-12 place-items-center rounded-xl border border-[#f34ba8]/30 bg-[#f34ba8]/10"><FlaskConical className="h-5 w-5 text-[#f34ba8]" /></div><span className="font-mono text-[10px] uppercase tracking-[.16em] text-[#ff82c0]">bancada prática</span></div><h2 className="mt-10 font-display text-2xl font-semibold">Criar testes com Gherkin</h2><p className="mt-3 max-w-md text-sm leading-6 text-[var(--app-pink-soft)]">Insira a história da P.O., escreva a feature e revise sua estrutura com critérios objetivos.</p><span className="mt-7 inline-flex items-center gap-2 font-mono text-xs text-[#ff82c0]">Abrir bancada de criação <ChevronRight className="h-4 w-4 transition group-hover:translate-x-1" /></span></button></div><div className="mt-12 flex flex-wrap gap-5 font-mono text-[11px] text-[var(--app-dim)]"><span><b className="text-[var(--app-text)]">05</b> módulos</span><span className="h-3 w-px bg-[var(--app-border-strong)]" /><span><b className="text-[var(--app-text)]">{questions.length}</b> questões</span><span className="h-3 w-px bg-[var(--app-border-strong)]" /><span><b className="text-[var(--app-text)]">100%</b> prática guiada</span></div></div></section><section className="mx-auto max-w-[1440px] px-5 py-16 lg:px-10"><div className="eyebrow">COMO FUNCIONA</div><div className="mt-7 grid gap-4 md:grid-cols-3"><div className="border-l border-[#18d8e8] pl-5"><span className="font-mono text-xs text-[#18d8e8]">01 / ESTUDE</span><h3 className="mt-4 font-display text-xl font-semibold">Entenda a regra</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Cada módulo explica o conceito, mostra sua estrutura e apresenta a referência oficial.</p></div><div className="border-l border-[#f34ba8] pl-5"><span className="font-mono text-xs text-[#f34ba8]">02 / PRATIQUE</span><h3 className="mt-4 font-display text-xl font-semibold">Escreva o comportamento</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Use sua história de usuário como contexto para criar exemplos mais claros.</p></div><div className="border-l border-[#ff9a72] pl-5"><span className="font-mono text-xs text-[#ff9a72]">03 / VERIFIQUE</span><h3 className="mt-4 font-display text-xl font-semibold">Verifique seu entendimento</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">A atividade aparece depois do conteúdo e explica o critério de cada resposta.</p></div></div></section><section className="border-t border-[var(--app-border-subtle)] bg-[var(--app-panel-deep)]"><div className="mx-auto flex max-w-[1440px] flex-col items-start justify-between gap-6 px-5 py-14 lg:flex-row lg:items-center lg:px-10"><div><div className="eyebrow">PRÁTICA RÁPIDA / GHERKIN</div><h2 className="mt-3 font-display text-3xl font-bold tracking-[-.04em]">Teste o que você acabou de estudar.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--app-muted)]">Escolha respostas sobre a estrutura oficial ou escreva um cenário mínimo. A correção é local, explícita e feita sem IA.</p></div><Button type="button" onClick={() => setMode("practice")} className="shrink-0 gap-2 bg-[#18d8e8] text-[var(--app-accent-foreground)] hover:bg-[#60eaf2]"><ClipboardCheck className="h-4 w-4" /> Abrir exercícios</Button></div></section></main>}

    {mode === "learn" && <main className="mx-auto max-w-[1440px] px-5 py-10 lg:px-10"><div className="mb-10 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><button onClick={() => setMode("home")} className="mb-7 inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.16em] text-[var(--app-dim)] hover:text-[var(--app-text)]"><ChevronLeft className="h-3 w-3" /> Início</button><div className="eyebrow">TRILHA DE APRENDIZADO</div><h1 className="mt-3 font-display text-4xl font-bold tracking-[-.05em]">Primeiro o conteúdo.<br /><span className="text-[#f34ba8]">Depois pratique.</span></h1></div><div className="min-w-[220px]"><div className="mb-2 flex justify-between font-mono text-[10px] text-[var(--app-dim)]"><span>PROGRESSO DA TRILHA</span><span>{progress}%</span></div><Progress value={progress} className="h-1.5 bg-[var(--app-soft)]" /></div></div><div className="grid gap-8 lg:grid-cols-[280px_1fr]"><aside className="space-y-2">{modules.map((item) => <button key={item.id} onClick={() => !item.locked && (setActiveModule(item.id), setSelectedLessonIndex(0), setSelected(null), setSubmitted(false))} className={`flex w-full items-center gap-4 rounded-xl border p-4 text-left transition ${activeModule === item.id ? "border-[#f34ba8]/70 bg-[var(--app-pink-panel)]" : "border-[var(--app-border-subtle)] bg-[var(--app-panel)] hover:border-[var(--app-border-strong)]"} ${item.locked ? "cursor-not-allowed opacity-45" : ""}`}><span className={`font-mono text-xs ${activeModule === item.id ? "text-[#f34ba8]" : "text-[#18d8e8]"}`}>{item.number}</span><span className="min-w-0 flex-1"><strong className="block truncate font-display text-sm">{item.title}</strong><small className="mt-1 block truncate text-xs text-[var(--app-dim)]">{item.level}</small><span className="mt-2 block h-1 w-full overflow-hidden rounded-full bg-[var(--app-soft)]"><span className="block h-full rounded-full bg-[#18d8e8]" style={{ width: `${moduleCompletion(item.id)}%` }} /></span></span>{item.locked && <LockKeyhole className="h-3.5 w-3.5 text-[var(--app-dim)]" />}</button>)}</aside><div className="space-y-6"><Card className="border-[var(--app-border)] bg-[var(--app-card)] text-[var(--app-text)]"><CardHeader className="border-b border-[var(--app-border)] bg-[var(--app-card-head)]"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#18d8e8]">MÓDULO {active.number} / {active.level.toUpperCase()}</div><CardTitle className="mt-2 font-display text-2xl">{active.title}</CardTitle></div><Badge className="border border-[#18d8e8]/30 bg-[#18d8e8]/10 text-[#18d8e8]">conteúdo</Badge></div></CardHeader><CardContent className="p-7"><p className="max-w-2xl text-lg leading-8 text-[var(--app-body)]">{active.description} Nesta etapa, você aprende a identificar a intenção de cada elemento antes de fazer a atividade de verificação.</p><div className="mt-8 grid gap-3 md:grid-cols-2 lg:grid-cols-3">{active.lessons.map((lesson, index) => <button key={lesson} type="button" onClick={() => setSelectedLessonIndex(index)} className={`rounded-xl border p-4 text-left transition ${completedLessons.includes(`${activeModule}-lesson-${index}`) ? "border-[#18d8e8]/50 bg-[#18d8e8]/10" : "border-[var(--app-border)] bg-[var(--app-panel-deep)] hover:border-[var(--app-border-strong)]"}`}><div className="flex items-center justify-between"><span className="font-mono text-[10px] text-[#18d8e8]">LIÇÃO 0{index + 1}</span>{completedLessons.includes(`${activeModule}-lesson-${index}`) ? <Check className="h-4 w-4 text-[#18d8e8]" /> : <span className="font-mono text-[10px] text-[var(--app-dim)]">marcar</span>}</div><p className="mt-4 text-sm leading-6 text-[var(--app-body-soft)]">{lesson}</p><span className="mt-4 block text-xs text-[var(--app-muted)]">{completedLessons.includes(`${activeModule}-lesson-${index}`) ? "Estudada · abrir conteúdo" : "Abrir conteúdo da lição"}</span></button>)}</div>{getLessonContent(activeModule, selectedLessonIndex) && <LessonDetailPanel lesson={getLessonContent(activeModule, selectedLessonIndex)!} completed={completedLessons.includes(`${activeModule}-lesson-${selectedLessonIndex}`)} draft={lessonDrafts[`${activeModule}-${selectedLessonIndex}`] ?? ""} onDraftChange={(value) => setLessonDrafts((items) => ({ ...items, [`${activeModule}-${selectedLessonIndex}`]: value }))} onToggleCompleted={() => toggleLesson(selectedLessonIndex)} />}<div className="mt-6 rounded-xl border border-[var(--app-border)] bg-[var(--app-cyan-panel)] p-4"><div className="flex items-center justify-between gap-4"><span className="font-mono text-[10px] uppercase tracking-[.12em] text-[var(--app-dim)]">PROGRESSO DO MÓDULO</span><span className="font-mono text-sm text-[#18d8e8]">{moduleCompletion(activeModule)}%</span></div><Progress value={moduleCompletion(activeModule)} className="mt-3 h-1.5 bg-[var(--app-soft)]" /><p className="mt-3 text-xs leading-5 text-[var(--app-muted)]">Conclua o conteúdo para liberar a atividade de verificação deste módulo.</p></div>{activeModule === "terminal" && <div className="mt-8 rounded-xl border border-[#18d8e8]/25 bg-[var(--app-cyan-panel)] p-5"><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#18d8e8]">MÓDULO DE PREPARAÇÃO</div><h3 className="mt-2 font-display text-xl font-semibold">Terminal e Node.js, sem mistério</h3><p className="mt-3 text-sm leading-6 text-[var(--app-cyan-text)]">O terminal é uma janela para conversar com o computador por comandos. Node.js permite executar JavaScript fora do navegador; npm instala e organiza os pacotes do projeto.</p><div className="mt-5 grid gap-3 md:grid-cols-2"><CodeBlock label="terminal / confirmar versão" code={`node --version\nnpm --version`} /><CodeBlock label="terminal / instalar e rodar" code={`npm install\nnpm run dev`} /></div><div className="mt-5 rounded-lg border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4 text-xs leading-5 text-[var(--app-muted)]"><strong className="text-[var(--app-text)]">Como praticar:</strong> abra o terminal na pasta do projeto, execute um comando por vez, leia a mensagem exibida e só avance quando entender o resultado.</div><div className="mt-6 rounded-xl border border-[#f34ba8]/25 bg-[var(--app-pink-panel)] p-5"><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#ff82c0]">PRÁTICA / TERMINAL</div><h3 className="mt-2 font-display text-xl font-semibold">Teste o comando antes de seguir.</h3><p className="mt-3 text-sm leading-6 text-[var(--app-pink-text)]">Digite o comando que você usaria no terminal e confira a resposta.</p><div className="mt-5 space-y-4">{terminalExercises.map((exercise) => <div key={exercise.id} className="rounded-lg border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4"><h4 className="font-display font-semibold">{exercise.title}</h4><p className="mt-2 text-xs text-[var(--app-muted)]">{exercise.prompt}</p><div className="mt-4 flex flex-col gap-2 sm:flex-row"><input value={terminalAnswers[exercise.id] ?? ""} onChange={(event) => setTerminalAnswers((items) => ({ ...items, [exercise.id]: event.target.value }))} placeholder="Digite o comando aqui" className="min-w-0 flex-1 rounded-lg border border-[var(--app-border)] bg-[var(--app-code)] px-3 py-2 font-mono text-sm text-[var(--app-code-strong)] outline-none focus:border-[#f34ba8]" aria-label={exercise.prompt} /><Button size="sm" onClick={() => validateTerminal(exercise)} className="bg-[#f34ba8] text-[var(--app-primary-foreground)] hover:bg-[#ff74bc]">Verificar</Button></div>{terminalFeedback[exercise.id] && <p className={`mt-3 rounded-lg border p-3 text-sm ${terminalFeedback[exercise.id].startsWith("Correto") ? "border-[#18d8e8]/30 bg-[#18d8e8]/10 text-[var(--app-success-text)]" : "border-[#ff9a72]/30 bg-[#ff9a72]/10 text-[var(--app-error-light)]"}`}>{terminalFeedback[exercise.id]}</p>}</div>)}</div></div></div>}{activeModule === "cypress" && <div className="mt-8 rounded-xl border border-[#f34ba8]/30 bg-[var(--app-pink-panel)] p-5"><div className="flex items-center gap-3"><Code2 className="h-5 w-5 text-[#f34ba8]" /><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#ff82c0]">EXERCÍCIO PRÁTICO</div><h3 className="mt-1 font-display font-semibold">Converta o cenário em Cypress</h3></div></div><p className="mt-4 text-sm leading-6 text-[var(--app-pink-text)]">Escreva os comandos que representam cada passo. Inclua a visita à página, a ação de adicionar e uma asserção sobre o carrinho.</p><div className="mt-4 rounded-lg border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4 font-mono text-xs leading-6 text-[var(--app-code-text)]">Dado que estou na página de produtos<br />Quando adiciono um produto ao carrinho<br />Então vejo o produto no carrinho</div><textarea value={conversionText} onChange={(event) => { setConversionText(event.target.value); setConversionFeedback(null); }} placeholder={`cy.visit('/produtos')\\ncy.contains('Adicionar').click()\\ncy.get('[data-testid=carrinho]').should('be.visible')`} className="mt-4 min-h-[150px] w-full resize-y rounded-xl border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4 font-mono text-sm leading-6 text-[var(--app-code-strong)] outline-none placeholder:text-[var(--app-placeholder)] focus:border-[#f34ba8]" spellCheck={false} /><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><span className="font-mono text-[10px] text-[var(--app-pink-muted)]">Critérios: visita · ação · clique · asserção</span><Button onClick={validateConversion} className="bg-[#f34ba8] text-[var(--app-primary-foreground)] hover:bg-[#ff74bc]">Verificar conversão <Check className="h-4 w-4" /></Button></div>{conversionFeedback && <div className={`mt-4 rounded-lg border p-3 text-sm ${conversionFeedback.startsWith("Conversão") ? "border-[#18d8e8]/30 bg-[#18d8e8]/10 text-[var(--app-success-text)]" : "border-[#ff9a72]/30 bg-[#ff9a72]/10 text-[var(--app-error-light)]"}`}>{conversionFeedback}</div>}{conversionFinished && <div className="mt-5 rounded-xl border border-[#18d8e8]/30 bg-[var(--app-cyan-panel)] p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="font-mono text-[10px] uppercase tracking-[.15em] text-[#18d8e8]">RESULTADO DO EXERCÍCIO</div><h4 className="mt-2 font-display text-xl font-semibold">{Object.values(conversionChecks).filter(Boolean).length} / {conversionCriteria.length} etapas corretas</h4></div><div className="grid h-14 w-14 place-items-center rounded-full border border-[#18d8e8]/40 bg-[#18d8e8]/10 font-mono text-sm text-[#18d8e8]">{Math.round((Object.values(conversionChecks).filter(Boolean).length / conversionCriteria.length) * 100)}%</div></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{conversionCriteria.map((item) => <div key={item.key} className={`flex items-center gap-3 rounded-lg border p-3 text-sm ${conversionChecks[item.key] ? "border-[#18d8e8]/20 bg-[#18d8e8]/5 text-[#c9f4f5]" : "border-[#ff9a72]/25 bg-[#ff9a72]/5 text-[var(--app-error-light)]"}`}>{conversionChecks[item.key] ? <Check className="h-4 w-4 text-[#18d8e8]" /> : <X className="h-4 w-4 text-[#ff9a72]" />}<span><strong>{item.label}</strong><small className="mt-1 block font-mono text-[10px] opacity-70">{conversionChecks[item.key] ? "Comando encontrado" : `Esperado: ${item.expected}`}</small></span></div>)}</div><Button onClick={() => { setConversionText(""); setConversionChecks({}); setConversionFeedback(null); setConversionFinished(false); }} variant="outline" className="mt-5 gap-2 border-[var(--app-border-strong)] bg-transparent text-[var(--app-text)] hover:bg-[var(--app-soft)]"><RotateCcw className="h-4 w-4" /> Tentar novamente</Button></div>}</div>}<div className="mt-8 flex flex-wrap items-center justify-between gap-4 border-t border-[var(--app-border)] pt-6"><a href="https://cucumber.io/docs/gherkin/reference/" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.12em] text-[#18d8e8] hover:underline">Ler documentação oficial <ExternalLink className="h-3 w-3" /></a><span className={`inline-flex items-center gap-2 rounded-lg border px-3 py-2 font-mono text-[10px] uppercase tracking-[.1em] ${allLessonsDone ? "border-[#18d8e8]/30 bg-[#18d8e8]/10 text-[#18d8e8]" : "border-[var(--app-border)] bg-[var(--app-soft)] text-[var(--app-dim)]"}`}>{allLessonsDone ? "Conteúdo concluído" : `${completedLessons.filter((item) => item.startsWith(`${activeModule}-lesson-`)).length}/${active.lessons.length} aulas concluídas`}{allLessonsDone && <Check className="h-4 w-4" />}</span></div></CardContent></Card>{allLessonsDone ? <Card className="border-[#f34ba8]/40 bg-[var(--app-card)] text-[var(--app-text)]"><CardHeader><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#f34ba8]">ETAPA 02 / PRÁTICA LIBERADA</div><CardTitle className="mt-2 font-display text-xl">Agora pratique o que você aprendeu</CardTitle></CardHeader><CardContent><p className="mb-6 text-sm leading-6 text-[var(--app-muted-strong)]">A atividade só fica disponível depois do conteúdo. Responda e leia a justificativa vinculada à regra oficial.</p><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-5"><div className="mb-5 flex items-center justify-between"><span className="font-mono text-[10px] text-[var(--app-dim)]">QUESTÃO {question.number} / {moduleQuestions.length}</span><Badge className="border-0 bg-[#f34ba8]/10 text-[#ff82c0]">1 ponto</Badge></div><h3 className="font-display text-lg font-semibold">{question.prompt}</h3><div className="mt-5 grid gap-3 sm:grid-cols-2">{question.options.map((option) => { const chosen = selected === option.id; const isAnswer = submitted && option.id === question.answer; const isWrong = submitted && chosen && !isAnswer; return <button key={option.id} disabled={submitted} onClick={() => setSelected(option.id)} className={`rounded-xl border p-4 text-left transition ${isAnswer ? "border-[#18d8e8] bg-[#18d8e8]/10" : isWrong ? "border-[#ff6b7a] bg-[#ff6b7a]/10" : chosen ? "border-[#f34ba8] bg-[#f34ba8]/10" : "border-[var(--app-border)] hover:border-[var(--app-border-strong)]"}`}><div className="flex justify-between"><span className="font-mono text-xs text-[#f34ba8]">{option.label}</span>{isAnswer && <Check className="h-4 w-4 text-[#18d8e8]" />}{isWrong && <X className="h-4 w-4 text-[#ff6b7a]" />}</div><p className="mt-2 text-sm leading-5 text-[var(--app-body-soft)]">{option.text}</p></button> })}</div>{submitted && <div className={`mt-5 rounded-xl border p-4 ${correct ? "border-[#18d8e8]/30 bg-[#18d8e8]/10" : "border-[#ff6b7a]/30 bg-[#ff6b7a]/10"}`}><strong className={correct ? "text-[#18d8e8]" : "text-[#ff8994]"}>{correct ? "Resposta correta" : "Revise este ponto"}</strong><p className="mt-2 text-sm leading-6 text-[var(--app-body-soft)]">{correct ? question.rationale : `Resposta esperada: ${question.options.find((option) => option.id === question.answer)?.label}. ${question.rationale}`}</p><a href={question.source ?? "https://cucumber.io/docs/gherkin/reference/"} target="_blank" rel="noreferrer" className="mt-3 inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.1em] text-[#18d8e8] hover:text-[var(--app-text)]"><ExternalLink className="h-3.5 w-3.5" /> Ler a documentação oficial</a></div>}<div className="mt-6 flex justify-end gap-3">{submitted && <Button variant="outline" onClick={() => { setSelected(null); setSubmitted(false); }} className="gap-2 border-[var(--app-border-strong)] bg-transparent text-[var(--app-text)] hover:bg-[var(--app-soft)]"><RotateCcw className="h-4 w-4" /> Tentar novamente</Button>}{submitted ? <Button onClick={nextQuestion} className="gap-2 bg-[#f34ba8] text-[var(--app-primary-foreground)] hover:bg-[#ff74bc]">Próxima questão <ChevronRight className="h-4 w-4" /></Button> : <Button disabled={!selected} onClick={submit} className="gap-2 bg-[#f34ba8] text-[var(--app-primary-foreground)] hover:bg-[#ff74bc]">Submeter resposta <ClipboardCheck className="h-4 w-4" /></Button>}</div></div></CardContent></Card> : <div className="flex items-center gap-3 rounded-xl border border-[#18d8e8]/20 bg-[var(--app-cyan-panel)] p-4 text-sm text-[var(--app-cyan-text)]"><CircleHelp className="h-4 w-4 shrink-0 text-[#18d8e8]" /><span>Leia cada aula e marque as três como concluídas para liberar a atividade de verificação.</span></div>}</div></div></main>}

    {mode === "create" && <main className="mx-auto max-w-[1440px] px-5 py-10 lg:px-10"><div className="mb-10 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><button onClick={() => setMode("home")} className="mb-7 inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.16em] text-[var(--app-dim)] hover:text-[var(--app-text)]"><ChevronLeft className="h-3 w-3" /> Início</button><div className="eyebrow">BANCADA DE CRIAÇÃO</div><h1 className="mt-3 font-display text-4xl font-bold tracking-[-.05em]">Crie testes<br /><span className="text-[#f34ba8]">com Gherkin.</span></h1></div><Badge className="w-fit border border-[#f34ba8]/30 bg-[#f34ba8]/10 px-3 py-2 text-[#ff82c0]">Prática livre</Badge></div><div className="grid gap-8 lg:grid-cols-[.8fr_1.2fr]"><Card className="border-[var(--app-border)] bg-[var(--app-card)] text-[var(--app-text)]"><CardHeader className="border-b border-[var(--app-border)] bg-[var(--app-card-head)]"><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#f34ba8]">01 / CONTEXTO</div><CardTitle className="mt-2 font-display text-xl">História da P.O.</CardTitle></CardHeader><CardContent className="p-6"><p className="mb-4 text-sm leading-6 text-[var(--app-muted-strong)]">Insira a história de usuário e os critérios de aceite que vão orientar sua escrita.</p><textarea value={story} onChange={(event) => setStory(event.target.value)} placeholder={starterStory} className="min-h-[230px] w-full resize-y rounded-xl border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4 font-mono text-sm leading-6 text-[var(--app-code-strong)] outline-none placeholder:text-[var(--app-placeholder)] focus:border-[#f34ba8]" /><div className="mt-3 flex flex-wrap items-center gap-2"><label htmlFor="po-pdf" className="inline-flex cursor-pointer items-center gap-2 rounded-lg border border-[#18d8e8]/30 bg-[#18d8e8]/10 px-3 py-2 font-mono text-[10px] uppercase tracking-[.1em] text-[#18d8e8] transition hover:border-[#18d8e8]"><FileUp className="h-3.5 w-3.5" /> Importar PDF</label><input id="po-pdf" type="file" accept="application/pdf" onChange={handlePdf} className="sr-only" /><span className="font-mono text-[10px] text-[var(--app-dim)]">ou cole o texto manualmente</span></div>{pdfName && <div className="mt-3 flex items-center gap-2 rounded-lg border border-[var(--app-border)] bg-[var(--app-panel-deep)] px-3 py-2 text-xs text-[var(--app-body-soft)]"><FileText className="h-3.5 w-3.5 text-[#18d8e8]" /><span className="truncate">{pdfName}</span>{pdfStatus && <span className="ml-auto text-[#18d8e8]">{pdfStatus}</span>}</div>}{!pdfName && pdfStatus && <p className="mt-3 text-xs text-[#ff9a72]">{pdfStatus}</p>}<div className="mt-4 flex items-center justify-between"><span className="font-mono text-[10px] text-[var(--app-dim)]">{story.length} caracteres · salvo neste navegador</span><Button onClick={() => localStorage.setItem("gherkin-story", story)} variant="outline" className="gap-2 border-[var(--app-border-strong)] bg-transparent text-[var(--app-text)] hover:bg-[var(--app-soft)]"><Save className="h-4 w-4" /> Salvar</Button></div></CardContent></Card><Card className="border-[var(--app-border)] bg-[var(--app-card)] text-[var(--app-text)]"><CardHeader className="border-b border-[var(--app-border)] bg-[var(--app-card-head)]"><div className="flex items-start justify-between gap-4"><div><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#18d8e8]">02 / ESPECIFICAÇÃO</div><CardTitle className="mt-2 font-display text-xl">Escreva sua feature</CardTitle></div><label className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.1em] text-[var(--app-dim)]">Idioma<select value={gherkinLanguage} onChange={(event) => setGherkinLanguage(event.target.value as GherkinLanguage)} className="rounded-md border border-[var(--app-border-strong)] bg-[var(--app-panel-deep)] px-2 py-1 text-[10px] text-[#18d8e8] outline-none focus:border-[#18d8e8]"><option value="pt">Português</option><option value="en">English</option></select></label></div></CardHeader><CardContent className="p-6"><p className="mb-4 text-sm leading-6 text-[var(--app-muted-strong)]">Use a história da P.O. como contexto. A verificação no final deste editor confere apenas a presença da estrutura mínima.</p><textarea value={featureText} onChange={(event) => { const value = event.target.value; setFeatureText(value); validateFeature(value); }} className="min-h-[360px] w-full resize-y rounded-xl border border-[var(--app-border)] bg-[var(--app-panel-deep)] p-4 font-mono text-sm leading-7 text-[var(--app-code-strong)] outline-none focus:border-[#18d8e8]" spellCheck={false} /><div className="mt-4 flex flex-wrap items-center justify-between gap-3"><span className="font-mono text-[10px] text-[var(--app-dim)]">Feature · Scenario · Given · When · Then</span><div className="flex flex-wrap gap-2"><Button onClick={() => setFeatureText(starterFeature)} variant="outline" className="border-[var(--app-border-strong)] bg-transparent text-[var(--app-text)] hover:bg-[var(--app-soft)]">Usar exemplo</Button><Button onClick={exportFeature} variant="outline" className="gap-2 border-[#f34ba8]/40 bg-transparent text-[#ff82c0] hover:bg-[#f34ba8]/10"><FileText className="h-4 w-4" /> Exportar .feature</Button><Button onClick={() => validateFeature()} className="gap-2 bg-[#18d8e8] text-[#071517] hover:bg-[#60eaf2]">Verificar estrutura <Check className="h-4 w-4" /></Button></div></div>{syntaxResult && <div className={`mt-5 rounded-xl border p-4 ${syntaxResult.startsWith("Estrutura") ? "border-[#18d8e8]/30 bg-[#18d8e8]/10" : "border-[#ff9a72]/30 bg-[#ff9a72]/10"}`}><p className="text-sm leading-6 text-[var(--app-cyan-text)]">{syntaxResult}</p></div>}</CardContent></Card></div><section className="mt-10 border-t border-[var(--app-border)] pt-10"><div className="mb-8"><div className="eyebrow">CYPRESS / PRIMEIROS PASSOS</div><h2 className="mt-3 font-display text-3xl font-bold tracking-[-.04em]">Do zero ao primeiro teste.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--app-muted)]">Siga esta ordem. Cada passo explica o que instalar, onde executar e em qual arquivo escrever.</p></div><div className="grid gap-3 md:grid-cols-2 lg:grid-cols-4"><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><span className="font-mono text-xs text-[#18d8e8]">01 / PREPARE</span><h3 className="mt-5 font-display font-semibold">Instale Node.js</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Tenha Node.js instalado e abra o terminal na pasta do seu projeto.</p></div><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><span className="font-mono text-xs text-[#f34ba8]">02 / INSTALE</span><h3 className="mt-5 font-display font-semibold">Adicione Cypress</h3><CodeBlock label="terminal / instalar" code={`npm install cypress --save-dev`} /></div><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><span className="font-mono text-xs text-[#ff9a72]">03 / ABRA</span><h3 className="mt-5 font-display font-semibold">Use o Launchpad</h3><CodeBlock label="terminal / abrir" code={`npx cypress open`} /><p className="mt-3 text-xs leading-5 text-[var(--app-muted)]">Na primeira abertura, escolha E2E Testing no Launchpad.</p></div><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><span className="font-mono text-xs text-[#18d8e8]">04 / ESCREVA</span><h3 className="mt-5 font-display font-semibold">Crie uma spec</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Escreva em cypress/e2e/login.cy.js e rode no navegador.</p></div></div><div className="mt-5 grid gap-4 lg:grid-cols-[1fr_1fr]"><div className="rounded-xl border border-[#18d8e8]/20 bg-[var(--app-cyan-panel)] p-5"><div className="flex items-center gap-3"><FolderTree className="h-5 w-5 text-[#18d8e8]" /><h3 className="font-display font-semibold">Onde cada coisa fica</h3></div><pre className="mt-4 overflow-x-auto font-mono text-xs leading-6 text-[var(--app-cyan-text)]">{`cypress/\n├─ e2e/       ← specs .cy.js\n├─ fixtures/  ← dados reutilizáveis\n└─ support/   ← comandos e configuração\ncypress.config.js ← configuração do projeto`}</pre></div><div className="rounded-xl border border-[#f34ba8]/20 bg-[var(--app-pink-panel)] p-5"><div className="flex items-center gap-3"><PlayCircle className="h-5 w-5 text-[#f34ba8]" /><h3 className="font-display font-semibold">Como executar</h3></div><p className="mt-3 text-sm leading-6 text-[var(--app-pink-text)]">No modo visual, use o Cypress aberto pelo Launchpad. No terminal, execute a suíte com:</p><div className="mt-3"><CodeBlock label="terminal / executar" code={`npx cypress run`} /></div><p className="mt-3 text-xs leading-5 text-[var(--app-pink-muted)]">O nome da spec precisa conter `.cy.` para ser encontrado pela configuração padrão.</p></div></div><div className="mt-8 grid gap-4 md:grid-cols-3"><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><Terminal className="h-5 w-5 text-[#f34ba8]" /><h3 className="mt-7 font-display font-semibold">Depois: conecte ao Cypress</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Transforme Dado, Quando e Então em preparação, ação e asserção observável.</p><div className="mt-4"><CodeBlock label="cypress/e2e/carrinho.cy.js" code={`describe('Carrinho', () => {\n  it('adiciona produto', () => {\n    cy.visit('/produtos')\n    cy.contains('Adicionar').click()\n    cy.get('[data-testid=carrinho]').should('be.visible')\n  })\n})`} /></div></div><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><Settings2 className="h-5 w-5 text-[#18d8e8]" /><h3 className="mt-7 font-display font-semibold">Organize com intenção</h3><p className="mt-2 text-sm leading-6 text-[var(--app-muted)]">Specs testam comportamentos; fixtures guardam dados; support concentra comandos compartilhados.</p></div><div className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-5"><FileText className="h-5 w-5 text-[#ff9a72]" /><h3 className="mt-7 font-display font-semibold">Consulte as regras</h3><a href="https://cucumber.io/docs/gherkin/reference/" target="_blank" rel="noreferrer" className="mt-2 inline-flex items-center gap-2 text-sm text-[#18d8e8] hover:underline">Gherkin Reference <ExternalLink className="h-3 w-3" /></a></div></div><div className="mt-10 grid gap-8 lg:grid-cols-[1.1fr_.9fr]"><div><div className="eyebrow">GLOSSÁRIO / COMANDOS</div><h2 className="mt-3 font-display text-3xl font-bold tracking-[-.04em]">Leia o comando. Entenda a intenção.</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[var(--app-muted)]">A documentação mostra a API; aqui você aprende a interpretar a assinatura, o elemento retornado e o momento certo de usar cada comando no fluxo.</p><div className="mt-6 space-y-3">{glossaryItems.map((item) => <div key={item.command} className="rounded-xl border border-[var(--app-border)] bg-[var(--app-panel)] p-4"><div className="flex flex-wrap items-center justify-between gap-3"><code className="font-mono text-sm text-[#18d8e8]">{item.command}</code><a href={item.docs} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-mono text-[10px] uppercase tracking-[.1em] text-[#ff82c0] hover:underline">Documentação <ExternalLink className="h-3 w-3" /></a></div><p className="mt-3 text-sm leading-6 text-[var(--app-body)]">{item.meaning}</p><p className="mt-2 text-xs leading-5 text-[var(--app-muted)]"><strong className="text-[#ffb0d3]">Quando usar:</strong> {item.when}</p></div>)}</div></div><div><div className="eyebrow">REGRESSÃO / ROTINA</div><h2 className="mt-3 font-display text-3xl font-bold tracking-[-.04em]">Como criar e agendar.</h2><p className="mt-3 text-sm leading-6 text-[var(--app-muted)]">Organize cenários estáveis em specs, execute no CI e programe uma rodada recorrente para descobrir regressões mesmo sem um novo deploy.</p><div className="mt-6 space-y-3">{[{ step: "01", title: "Separe o fluxo", text: "Crie uma spec por área ou comportamento e use nomes .cy.js." }, { step: "02", title: "Prepare o ambiente", text: "Instale dependências, faça o build e suba a aplicação antes do Cypress." }, { step: "03", title: "Execute no CI", text: "Use a ação oficial do Cypress para instalar, iniciar e rodar os testes." }, { step: "04", title: "Agende a rotina", text: "Use schedule com cron no GitHub Actions; o horário padrão é interpretado em UTC." }].map((item) => <div key={item.step} className="flex gap-4 rounded-xl border border-[#f34ba8]/20 bg-[var(--app-pink-panel)] p-4"><span className="font-mono text-xs text-[#f34ba8]">{item.step}</span><div><h3 className="font-display font-semibold">{item.title}</h3><p className="mt-1 text-xs leading-5 text-[var(--app-pink-text)]">{item.text}</p></div></div>)}</div><div className="mt-5"><CodeBlock label=".github/workflows/cypress-regressao.yml" code={regressionWorkflow} /></div><div className="mt-4 flex flex-wrap gap-3"><a href="https://docs.cypress.io/app/continuous-integration/github-actions" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.1em] text-[#18d8e8] hover:underline">Guia Cypress CI <ExternalLink className="h-3 w-3" /></a><a href="https://docs.github.com/actions/using-workflows/events-that-trigger-workflows#schedule" target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 font-mono text-[10px] uppercase tracking-[.1em] text-[#ff82c0] hover:underline">Cron no GitHub Actions <ExternalLink className="h-3 w-3" /></a></div></div></div></section><CypressLearningPanel /></main>}
    {mode === "practice" && <main><GherkinPracticePanel onBack={() => setMode("home")} /></main>}
    <footer className="border-t border-[var(--app-border-subtle)] bg-[var(--app-footer)]"><div className="mx-auto flex max-w-[1440px] flex-col gap-3 px-5 py-7 text-xs text-[var(--app-dim)] sm:flex-row sm:items-center sm:justify-between lg:px-10"><span className="font-mono">GHERKIN ACADEMY / BANCADA DE QUALIDADE</span><span>Aprenda, escreva e valide comportamentos.</span></div></footer>
  </div>;
}
